  function trimCanvas(img){const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const cx=c.getContext('2d');cx.drawImage(img,0,0);const data=cx.getImageData(0,0,c.width,c.height).data;let minX=c.width,minY=c.height,maxX=-1,maxY=-1;for(let y=0;y<c.height;y++){for(let x=0;x<c.width;x++){const i=(y*c.width+x)*4,r=data[i],g=data[i+1],b=data[i+2],a=data[i+3];if(a>12&&(r<246||g<246||b<246)){if(x<minX)minX=x;if(y<minY)minY=y;if(x>maxX)maxX=x;if(y>maxY)maxY=y}}}if(maxX<0)return {img,src:img.src,w:img.naturalWidth,h:img.naturalHeight};const pad=2,minArea=c.width*c.height*.08,tw=maxX-minX+1,th=maxY-minY+1;if(tw*th>c.width*c.height*.92||tw*th<minArea)return {img,src:img.src,w:img.naturalWidth,h:img.naturalHeight};minX=Math.max(0,minX-pad);minY=Math.max(0,minY-pad);maxX=Math.min(c.width-1,maxX+pad);maxY=Math.min(c.height-1,maxY+pad);const out=document.createElement('canvas');out.width=maxX-minX+1;out.height=maxY-minY+1;out.getContext('2d').drawImage(c,minX,minY,out.width,out.height,0,0,out.width,out.height);const src=out.toDataURL('image/png'),trimmed=new Image();trimmed.src=src;return {img:trimmed,src,w:out.width,h:out.height}}
